def _fit_period(observations, limit):
    """Return the shortest complete residue coloring consistent with observations."""
    for p in range(1, limit + 1):
        colors = {}
        for position, color in observations:
            residue = position % p
            if residue in colors and colors[residue] != color:
                break
            colors[residue] = color
        else:
            if len(colors) == p:
                return p, colors
    return None


def transform(grid):
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w or any(len(row) != w for row in grid):
        raise ValueError("grid must be nonempty and rectangular")

    # Full-width uniform rows are a one-dimensional periodic row-color field.
    clues = []
    row_mode = True
    for r, row in enumerate(grid):
        vals = set(row)
        if vals != {0}:
            if 0 in vals or len(vals) != 1:
                row_mode = False
                break
            clues.append((r, row[0]))
    if row_mode and clues:
        fit = _fit_period(clues, h)
        if fit:
            p, colors = fit
            return [[colors[r % p] for _ in range(w)] for r in range(h)]

    cells = [(r, c, v) for r, row in enumerate(grid)
             for c, v in enumerate(row) if v]
    fits = []
    # Each candidate coordinate is constant along one diagonal orientation.
    for name, position, limit in (
        ("sum", lambda r, c: r + c, h + w - 1),
        ("difference", lambda r, c: c - r, h + w - 1),
    ):
        observations = [(position(r, c), v) for r, c, v in cells]
        fit = _fit_period(observations, limit)
        if fit:
            p, colors = fit
            fits.append((p, name, colors))
    if not fits:
        raise ValueError("no complete periodic field fits the clues")
    # Smallest period is the simplest completion supported by the full fixture.
    p, name, colors = min(fits, key=lambda x: x[0])
    if name == "sum":
        return [[colors[(r + c) % p] for c in range(w)] for r in range(h)]
    return [[colors[(c - r) % p] for c in range(w)] for r in range(h)]


